<?php
$statusClass = static fn (string $status): string => $status === 'completed' ? 'badge-success' : ($status === 'cancelled' ? 'badge-secondary' : 'badge-light');
?>
<div class="patient-prescriptions-grid">
<?php foreach ($prescriptions as $prescription): ?><article class="patient-prescription-card"><div class="patient-prescription-card-head"><div><span class="patient-eyebrow">Prescription</span><h3 title="<?= esc($prescription['prescription_number']) ?>"><?= esc($prescription['prescription_number']) ?></h3></div><span class="badge <?= $statusClass((string) $prescription['status']) ?> patient-status-badge"><?= esc($prescription['status_label']) ?></span></div><div class="patient-prescription-card-doctor"><span class="patient-avatar" aria-hidden="true"><?= esc(strtoupper(substr((string) ($prescription['doctor_first_name'] ?? 'D'), 0, 1))) ?></span><div><strong>Dr. <?= esc(trim(($prescription['doctor_first_name'] ?? '') . ' ' . ($prescription['doctor_last_name'] ?? ''))) ?></strong><small><?= esc($prescription['specialization'] ?: 'Specialization not recorded') ?></small></div></div><dl class="patient-prescription-card-details"><div><dt>Date</dt><dd><?= esc($prescription['prescription_date_display']) ?></dd></div><div><dt>Medicines</dt><dd><?= (int) $prescription['medicine_count'] ?></dd></div></dl><p class="patient-card-meta"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Updated <?= esc($prescription['updated_at'] ?? '—') ?></p><div class="patient-prescription-card-actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-prescription-view" type="button" data-id="<?= (int) $prescription['id'] ?>" data-toggle="modal" data-target="#patient-prescription-detail-modal">View prescription</button><button class="dropdown-item patient-prescription-print-row" type="button" data-id="<?= (int) $prescription['id'] ?>">Print</button></div></div></div></article><?php endforeach; ?>
<?php if ($prescriptions === []): ?><div class="patient-empty-state"><i class="bi bi-prescription2" aria-hidden="true"></i><strong>No prescriptions found</strong><span>Try clearing filters.</span></div><?php endif; ?></div>
